156	#[post("/auth/logout")]
157	pub async fn logout(pool: web::Data<PgPool>, req: HttpRequest) -> Result<HttpResponse, ApiAppError> {
158	    if let Some(c) = req.cookie(SESSION_COOKIE) {
159	        // IMPORTANT: look up the session BEFORE revoking it.
160	        // SessionService::lookup filters `revoked_at IS NULL`, so calling
161	        // revoke() first causes the subsequent lookup to return None and
162	        // ApiTokenService::revoke_for_user is never reached — leaving the
163	        // short-lived API token active until its 15-minute TTL expires.
164	        let user_id = SessionService::lookup(pool.get_ref(), c.value())
165	            .await
166	            .ok()
167	            .flatten()
168	            .map(|info| info.user_id);
169	
170	        SessionService::revoke(pool.get_ref(), c.value()).await?;
171	
172	        if let Some(uid) = user_id {
173	            ApiTokenService::revoke_for_user(pool.get_ref(), uid).await?;
174	        }
175	    }
176	    Ok(HttpResponse::Ok()
177	        .cookie(Cookie::build(SESSION_COOKIE, "").path("/").max_age(actix_web::cookie::time::Duration::ZERO).finish())
178	        .json(serde_json::json!({"ok": true})))
179	}
