181	#[get("/auth/session")]
182	pub async fn current_session(
183	    pool: web::Data<PgPool>,
184	    req: HttpRequest,
185	) -> Result<HttpResponse, ApiAppError> {
186	    let cookie = req
187	        .cookie(SESSION_COOKIE)
188	        .ok_or_else(|| ApiAppError::Unauthorized("no session".into()))?;
189	    let info = SessionService::lookup(pool.get_ref(), cookie.value())
190	        .await?
191	        .ok_or_else(|| ApiAppError::Unauthorized("no session".into()))?;
192	    let principal = rbac::load_principal(pool.get_ref(), info.user_id).await?;
193	
194	    // Surface the expiry of the user's active API token so the client knows
195	    // when to re-authenticate.  The field is Option<DateTime<Utc>>, so clients
196	    // that previously received null continue to parse the response correctly.
197	    let token_expires_at: Option<DateTime<Utc>> = sqlx::query_as(
198	        "SELECT expires_at FROM api_tokens
199	         WHERE user_id = $1 AND revoked_at IS NULL AND expires_at > NOW()
200	         ORDER BY expires_at DESC LIMIT 1",
201	    )
202	    .bind(info.user_id)
203	    .fetch_optional(pool.get_ref())
204	    .await?
205	    .map(|(exp,)| exp);
206	
207	    Ok(HttpResponse::Ok().json(SessionResponse { principal, token_expires_at }))
208	}
