216	#[post("/auth/recovery/request")]
217	pub async fn request_recovery(
218	    pool: web::Data<PgPool>,
219	    body: web::Json<RecoveryRequestInput>,
220	) -> Result<HttpResponse, ApiAppError> {
221	    let user: Option<(Uuid,)> = sqlx::query_as("SELECT id FROM users WHERE lower(email) = $1")
222	        .bind(body.email.trim().to_lowercase())
223	        .fetch_optional(pool.get_ref())
224	        .await?;
225	    // Always respond OK to avoid user-enumeration.
226	    if let Some((id,)) = user {
227	        sqlx::query("INSERT INTO recovery_requests (user_id) VALUES ($1)")
228	            .bind(id)
229	            .execute(pool.get_ref())
230	            .await?;
231	    }
232	    Ok(HttpResponse::Ok().json(serde_json::json!({"ok": true})))
233	}
