235	// ── Unit tests ────────────────────────────────────────────────────────────────
236	//
237	// Pure-function tests that require no database or HTTP server.
238	//
239	// Session-level integration tests (logout order-of-operations, session/token
240	// expiry flow, CSRF behaviour) live in apps/backend-api/tests/ and require a
241	// live Postgres instance.
242	//
243	// Key invariants covered by those integration tests:
244	//   1. POST /auth/logout resolves the session user_id BEFORE marking the
245	//      session revoked, ensuring ApiTokenService::revoke_for_user is reached.
246	//   2. GET /auth/session returns HTTP 401 when the cookie is absent or revoked.
247	//   3. GET /auth/session populates `token_expires_at` when an active API token
248	//      exists, and returns null when no active token is present.
249	
250	#[cfg(test)]
251	mod tests {
252	    use actix_web::test::TestRequest;
253	
254	    use super::*;
255	
256	    // ── client_ip extraction ──────────────────────────────────────────────────
257	
258	    #[test]
259	    fn client_ip_prefers_first_x_forwarded_for_entry() {
260	        let req = TestRequest::get()
261	            .insert_header(("x-forwarded-for", "203.0.113.5, 10.0.0.1"))
262	            .to_http_request();
263	        assert_eq!(client_ip(&req), "203.0.113.5");
264	    }
265	
266	    #[test]
267	    fn client_ip_single_xff_entry() {
268	        let req = TestRequest::get()
269	            .insert_header(("x-forwarded-for", "198.51.100.42"))
270	            .to_http_request();
271	        assert_eq!(client_ip(&req), "198.51.100.42");
272	    }
273	
274	    #[test]
275	    fn client_ip_returns_non_empty_without_xff() {
276	        let req = TestRequest::get().to_http_request();
277	        // No XFF header and no real connection peer — falls back to "unknown".
278	        let ip = client_ip(&req);
279	        assert!(!ip.is_empty());
280	    }
281	
282	    // ── session endpoint response shape ──────────────────────────────────────
283	
284	    #[test]
285	    fn session_response_serializes_token_expires_at_as_null_when_none() {
286	        use uuid::Uuid;
287	        use std::collections::HashSet;
288	        use crate::security::rbac::{Principal, Scope};
289	
290	        let p = Principal {
291	            user_id: Uuid::new_v4(),
292	            email: "test@example.com".into(),
293	            roles: vec![],
294	            permissions: HashSet::new(),
295	            scopes: vec![],
296	        };
297	        let resp = SessionResponse { principal: p, token_expires_at: None };
298	        let json = serde_json::to_value(&resp).expect("serialize");
299	        assert!(json["token_expires_at"].is_null());
300	    }
301	}
