151	/// List moderation queue items, optionally filtered by status.
152	/// Requires `moderation:review` permission.
153	pub async fn list_queue(
154	    pool: &PgPool,
155	    p: &Principal,
156	    status_filter: Option<&str>,
157	) -> Result<Vec<ModerationQueueItem>, ApiAppError> {
158	    p.require("moderation:review")?;
159	
160	    let rows: Vec<(
161	        Uuid,
162	        String,
163	        Option<Uuid>,
164	        String,
165	        Vec<String>,
166	        String,
167	        String,
168	        chrono::DateTime<chrono::Utc>,
169	        Option<Uuid>,
170	        Option<chrono::DateTime<chrono::Utc>>,
171	    )> = match status_filter {
172	        Some(status) => sqlx::query_as(
173	            "SELECT id, content_type, content_ref_id, content_snippet,
174	                    matched_keywords, severity, status, flagged_at,
175	                    reviewed_by, reviewed_at
176	             FROM moderation_queue
177	             WHERE status = $1
178	             ORDER BY flagged_at DESC",
179	        )
180	        .bind(status)
181	        .fetch_all(pool)
182	        .await?,
183	        None => sqlx::query_as(
184	            "SELECT id, content_type, content_ref_id, content_snippet,
185	                    matched_keywords, severity, status, flagged_at,
186	                    reviewed_by, reviewed_at
187	             FROM moderation_queue
188	             ORDER BY flagged_at DESC",
189	        )
190	        .fetch_all(pool)
191	        .await?,
192	    };
193	
194	    Ok(rows
195	        .into_iter()
196	        .map(
197	            |(
198	                id,
199	                content_type,
200	                content_ref_id,
201	                content_snippet,
202	                matched_keywords,
203	                severity,
204	                status,
205	                flagged_at,
206	                reviewed_by,
207	                reviewed_at,
208	            )| ModerationQueueItem {
209	                id,
210	                content_type,
211	                content_ref_id,
212	                content_snippet,
213	                matched_keywords,
214	                severity,
215	                status,
216	                flagged_at,
217	                reviewed_by,
218	                reviewed_at,
219	            },
220	        )
221	        .collect())
222	}
