224	/// Record a review decision on a moderation queue item.
225	/// Requires `moderation:review` permission.
226	pub async fn review_item(
227	    pool: &PgPool,
228	    p: &Principal,
229	    item_id: Uuid,
230	    input: ReviewInput,
231	) -> Result<(), ApiAppError> {
232	    p.require("moderation:review")?;
233	
234	    if !ALLOWED_REVIEW_ACTIONS.contains(&input.action.as_str()) {
235	        return Err(ApiAppError::BadRequest(format!(
236	            "action must be one of: {}",
237	            ALLOWED_REVIEW_ACTIONS.join(", ")
238	        )));
239	    }
240	
241	    let affected = sqlx::query(
242	        "UPDATE moderation_queue
243	         SET status = $2, reviewed_by = $3, reviewed_at = NOW()
244	         WHERE id = $1",
245	    )
246	    .bind(item_id)
247	    .bind(&input.action)
248	    .bind(p.user_id)
249	    .execute(pool)
250	    .await?
251	    .rows_affected();
252	
253	    if affected == 0 {
254	        return Err(ApiAppError::NotFound);
255	    }
256	
257	    // Use the schema-correct column names:
258	    //   `performed_by` (UUID FK) — who performed the review action.
259	    //   `note`         (TEXT)    — the reviewer's human-readable note, if any.
260	    // The `detail` JSONB column is reserved for flag events that carry
261	    // structured keyword metadata; review events have no additional structured
262	    // payload beyond what the dedicated columns already capture.
263	    sqlx::query(
264	        "INSERT INTO moderation_audit_log (queue_item_id, action, performed_by, note)
265	         VALUES ($1, $2, $3, $4)",
266	    )
267	    .bind(item_id)
268	    .bind(&input.action)
269	    .bind(p.user_id)
270	    .bind(input.note.as_deref())
271	    .execute(pool)
272	    .await?;
273	
274	    Ok(())
275	}
