277	/// List all keyword policies.  Requires `admin:users`.
278	pub async fn list_policies(
279	    pool: &PgPool,
280	    p: &Principal,
281	) -> Result<Vec<KeywordPolicy>, ApiAppError> {
282	    p.require("admin:users")?;
283	
284	    let rows: Vec<(Uuid, String, String, bool, chrono::DateTime<chrono::Utc>)> =
285	        sqlx::query_as(
286	            "SELECT id, keyword, severity, is_active, created_at
287	             FROM keyword_policies
288	             ORDER BY keyword",
289	        )
290	        .fetch_all(pool)
291	        .await?;
292	
293	    Ok(rows
294	        .into_iter()
295	        .map(|(id, keyword, severity, is_active, created_at)| KeywordPolicy {
