305	/// Create (or reactivate) a keyword policy.  Requires `admin:users`.
306	pub async fn create_policy(
307	    pool: &PgPool,
308	    p: &Principal,
309	    input: CreatePolicyInput,
310	) -> Result<KeywordPolicy, ApiAppError> {
311	    p.require("admin:users")?;
312	
313	    let keyword = input.keyword.trim().to_lowercase();
314	    if keyword.is_empty() {
315	        return Err(ApiAppError::BadRequest("keyword must not be empty".into()));
316	    }
317	
318	    let severity = input.severity.as_deref().unwrap_or("medium");
319	    if !ALLOWED_SEVERITIES.contains(&severity) {
320	        return Err(ApiAppError::BadRequest(format!(
321	            "severity must be one of: {}",
322	            ALLOWED_SEVERITIES.join(", ")
323	        )));
324	    }
325	
326	    let (id, stored_keyword, stored_severity, is_active, created_at): (
327	        Uuid,
328	        String,
329	        String,
330	        bool,
331	        chrono::DateTime<chrono::Utc>,
332	    ) = sqlx::query_as(
333	        "INSERT INTO keyword_policies (keyword, severity, is_active)
334	         VALUES ($1, $2, true)
335	         ON CONFLICT (keyword) DO UPDATE
336	             SET severity = EXCLUDED.severity,
337	                 is_active = true
338	         RETURNING id, keyword, severity, is_active, created_at",
339	    )
340	    .bind(&keyword)
341	    .bind(severity)
342	    .fetch_one(pool)
343	    .await?;
344	
345	    Ok(KeywordPolicy {
346	        id,
347	        keyword: stored_keyword,
348	        severity: stored_severity,
349	        is_active,
350	        created_at,
351	    })
352	}
