354	/// Delete a keyword policy by ID.  Requires `admin:users`.
355	/// Keyword policies are not foreign-key referenced, so hard delete is safe.
356	pub async fn delete_policy(pool: &PgPool, p: &Principal, id: Uuid) -> Result<(), ApiAppError> {
357	    p.require("admin:users")?;
358	
359	    let affected = sqlx::query("DELETE FROM keyword_policies WHERE id = $1")
360	        .bind(id)
361	        .execute(pool)
362	        .await?
363	        .rows_affected();
364	
365	    if affected == 0 {
366	        return Err(ApiAppError::NotFound);
367	    }
368	    Ok(())
369	}
