32	#[get("/inventory/catalog")]
33	pub async fn catalog(pool: web::Data<PgPool>, req: HttpRequest) -> Result<HttpResponse, ApiAppError> {
34	    let p = principal(&req)?;
35	    p.require("inventory:read").or_else(|_| p.require("requisitions:write"))?;
36	    // Show stock at the FIRST department-scoped site (Phase 3 demo).
37	    // The site picker is wired in a later phase.
38	    let scope_any = p.permissions.contains("scope:any");
39	    let dept_refs: Vec<String> = p.scopes.iter()
40	        .filter(|s| s.kind == ScopeKind::Department)
41	        .map(|s| s.reference.clone()).collect();
42	    let site_id: Option<(Uuid,)> = if scope_any {
43	        sqlx::query_as("SELECT id FROM sites ORDER BY name LIMIT 1").fetch_optional(pool.get_ref()).await?
44	    } else if let Some(d) = dept_refs.first() {
45	        sqlx::query_as("SELECT site_id FROM departments WHERE id = $1::uuid")
46	            .bind(d).fetch_optional(pool.get_ref()).await?
47	    } else { None };
48	    let site_id = site_id.map(|s| s.0);
49	
50	    let rows: Vec<(Uuid, String, String, String, i64, bool, String, Option<i32>)> = sqlx::query_as(
51	        "SELECT i.id, i.sku, i.name, i.unit, i.unit_price_cents, c.controlled, c.label,
52	                (SELECT on_hand FROM inventory_stock_by_site s WHERE s.item_id=i.id AND s.site_id=$1)
53	         FROM inventory_items i JOIN inventory_categories c ON c.id=i.category_id
54	         WHERE i.is_active ORDER BY i.name",
55	    ).bind(site_id).fetch_all(pool.get_ref()).await?;
56	
57	    let out: Vec<CatalogItem> = rows.into_iter().map(|r| CatalogItem {
58	        id: r.0, sku: r.1, name: r.2, unit: r.3,
59	        unit_price_cents: r.4, controlled: r.5, category: r.6,
60	        on_hand: r.7.unwrap_or(0),
61	    }).collect();
62	    Ok(HttpResponse::Ok().json(out))
63	}
