87	pub async fn load_principal(pool: &PgPool, user_id: Uuid) -> Result<Principal> {
88	    let user: (Uuid, String) = sqlx::query_as("SELECT id, email FROM users WHERE id = $1 AND is_active")
89	        .bind(user_id)
90	        .fetch_one(pool)
91	        .await?;
92	
93	    let roles: Vec<(String,)> = sqlx::query_as(
94	        "SELECT r.key FROM roles r
95	         JOIN user_role_assignments ura ON ura.role_id = r.id
96	         WHERE ura.user_id = $1",
97	    )
98	    .bind(user_id)
99	    .fetch_all(pool)
100	    .await?;
101	
102	    let perms: Vec<(String,)> = sqlx::query_as(
103	        "SELECT DISTINCT p.key FROM permissions p
104	         JOIN role_permissions rp ON rp.permission_id = p.id
105	         JOIN user_role_assignments ura ON ura.role_id = rp.role_id
106	         WHERE ura.user_id = $1",
107	    )
108	    .bind(user_id)
109	    .fetch_all(pool)
110	    .await?;
111	
112	    let scopes: Vec<(String, String)> = sqlx::query_as(
113	        "SELECT scope_kind, scope_ref FROM user_scopes WHERE user_id = $1",
114	    )
115	    .bind(user_id)
116	    .fetch_all(pool)
117	    .await?;
118	
119	    Ok(Principal {
120	        user_id: user.0,
121	        email: user.1,
122	        roles: roles.into_iter().map(|(k,)| k).collect(),
123	        permissions: perms.into_iter().map(|(k,)| k).collect(),
124	        scopes: scopes
125	            .into_iter()
126	            .filter_map(|(k, r)| ScopeKind::parse(&k).map(|kind| Scope { kind, reference: r }))
127	            .collect(),
128	    })
129	}
