5	#[derive(Debug, Error)]
6	pub enum ApiAppError {
7	    #[error("not found")]
8	    NotFound,
9	    #[error("bad request: {0}")]
10	    BadRequest(String),
11	    #[error("conflict: {0}")]
12	    Conflict(String),
13	    #[error("unauthorized: {0}")]
14	    Unauthorized(String),
15	    #[error("forbidden: {0}")]
16	    Forbidden(String),
17	    #[error("rate limited (retry after {0}s)")]
18	    RateLimited(u64),
19	    #[error("internal: {0}")]
20	    Internal(String),
21	}
22	
23	impl ResponseError for ApiAppError {
24	    fn status_code(&self) -> StatusCode {
25	        match self {
26	            Self::NotFound => StatusCode::NOT_FOUND,
27	            Self::BadRequest(_) => StatusCode::BAD_REQUEST,
28	            Self::Conflict(_) => StatusCode::CONFLICT,
29	            Self::Unauthorized(_) => StatusCode::UNAUTHORIZED,
30	            Self::Forbidden(_) => StatusCode::FORBIDDEN,
31	            Self::RateLimited(_) => StatusCode::TOO_MANY_REQUESTS,
32	            Self::Internal(_) => StatusCode::INTERNAL_SERVER_ERROR,
33	        }
34	    }
35	
36	    fn error_response(&self) -> HttpResponse {
37	        let (code, message) = match self {
38	            Self::NotFound => ("not_found".into(), self.to_string()),
39	            Self::BadRequest(m) => ("bad_request".into(), m.clone()),
40	            Self::Conflict(m) => ("conflict".into(), m.clone()),
41	            Self::Unauthorized(m) => ("unauthorized".into(), m.clone()),
42	            Self::Forbidden(m) => ("forbidden".into(), m.clone()),
43	            Self::RateLimited(s) => ("rate_limited".into(), format!("retry after {s}s")),
44	            Self::Internal(m) => ("internal".into(), m.clone()),
45	        };
46	        let mut resp = HttpResponse::build(self.status_code());
47	        if let Self::RateLimited(s) = self {
48	            resp.insert_header(("Retry-After", s.to_string()));
49	        }
50	        resp.json(ApiError { code, message })
51	    }
52	}
