128	/// Pure read-authorization predicate for a single requisition.
129	/// Policy (mirrors inbox and load_detail):
130	///   owner  OR  (has `requisitions:approve` AND dept-scoped)  OR  scope:any
131	///
132	/// Extracted as a named helper so both `load_detail` and `load_issue_record`
133	/// share exactly one copy of the policy — changes here propagate to both.
134	fn can_read_requisition(p: &Principal, requester_id: Uuid, department_id: Uuid) -> bool {
135	    if p.permissions.contains("scope:any") {
136	        return true;
137	    }
138	    if p.user_id == requester_id {
139	        return true;
140	    }
141	    if p.permissions.contains("requisitions:approve") {
142	        let dept_ok = p
143	            .scopes
144	            .iter()
145	            .any(|s| s.kind == ScopeKind::Department && s.reference == department_id.to_string());
146	        if dept_ok {
147	            return true;
148	        }
149	    }
150	    false
151	}
