163	        sqlx::query_as("SELECT department_id FROM requisitions WHERE id = $1")
164	            .bind(req_id)
165	            .fetch_optional(pool)
166	            .await?;
167	    let (dept_id,) = row.ok_or(ApiAppError::NotFound)?;
168	    assert_dept_scope(p, dept_id)
169	}
