174	pub async fn create_draft(
175	    pool: &PgPool,
176	    p: &Principal,
177	    input: CreateRequisitionInput,
178	) -> Result<RequisitionDetail, ApiAppError> {
179	    p.require("requisitions:write")?;
180	    assert_dept_scope(p, input.department_id)?;
181	    if input.needed_by < chrono::Local::now().date_naive() {
182	        return Err(ApiAppError::BadRequest("needed_by must be today or a future date".into()));
183	    }
184	    if input.justification.trim().is_empty() {
185	        return Err(ApiAppError::BadRequest("justification required".into()));
186	    }
187	    if input.lines.is_empty() {
188	        return Err(ApiAppError::BadRequest("at least one line required".into()));
189	    }
190	    for l in &input.lines {
191	        if l.quantity <= 0 {
192	            return Err(ApiAppError::BadRequest("quantities must be > 0".into()));
193	        }
194	    }
195	
196	    let mut tx = pool.begin().await?;
197	
198	    // Derive the site from the department.
199	    let site_row: Option<(Uuid,)> = sqlx::query_as("SELECT site_id FROM departments WHERE id=$1")
200	        .bind(input.department_id).fetch_optional(&mut *tx).await?;
201	    let site_id = site_row.ok_or_else(|| ApiAppError::BadRequest("unknown department".into()))?.0;
202	
203	    // Look up items + categories + on_hand at the requisition's site.
204	    let mut total: i64 = 0;
205	    let mut controlled = false;
