#[cfg(test)]
mod tests {
    // ── permission denial wiring ──────────────────────────────────────────────

    /// Confirms the HTTP status constant used to gate permission-denial
    /// recording is exactly 403 Forbidden — any typo here would silently
    /// disable the anomaly signal for all authenticated routes.
    #[test]
    fn forbidden_status_code_is_403() {
        assert_eq!(
            actix_web::http::StatusCode::FORBIDDEN.as_u16(),
            403,
            "permission denial recording is gated on HTTP 403; value must be exact"
        );
    }

    /// Confirms that authentication failures (401 Unauthorized) are NOT treated
    /// as permission denials — those map to `record_auth_failure`, not
    /// `record_permission_denial`.
    #[test]
    fn unauthorized_status_code_is_not_forbidden() {
        let unauth = actix_web::http::StatusCode::UNAUTHORIZED;
        let forbidden = actix_web::http::StatusCode::FORBIDDEN;
        assert_ne!(
            unauth, forbidden,
            "401 and 403 must remain distinct; auth failures != permission denials"
        );
    }

    /// Verifies that the IpGuard short-circuit paths (blacklist, rate-limit)
    /// produce right-body responses so they bypass the left-body handler path.
    /// Ensures the map_into_right_body / map_into_left_body pairing is intact.
    #[test]
    fn client_ip_extraction_returns_non_empty_string() {
        use actix_web::test::TestRequest;
        let req = TestRequest::get()
            .insert_header(("x-forwarded-for", "10.0.0.1, 192.168.1.1"))
            .to_srv_request();
        // Re-implement the same extraction logic to test it in isolation.
        let ip = if let Some(h) = req.headers().get("x-forwarded-for") {
            if let Ok(v) = h.to_str() {
                if let Some(first) = v.split(',').next() {
                    first.trim().to_string()
                } else {
                    String::new()
                }
            } else {
                String::new()
            }
        } else {
            String::new()
        };
        assert_eq!(ip, "10.0.0.1");
    }
}"}

