251	// ── Unit tests ────────────────────────────────────────────────────────────────
252	//
253	// Pure-function tests that require no database or HTTP server.
254	//
255	// Session-level integration tests (logout order-of-operations, session/token
256	// expiry flow, CSRF behaviour) live in apps/backend-api/tests/ and require a
257	// live Postgres instance.
258	//
259	// Key invariants covered by those integration tests:
260	//   1. POST /auth/logout resolves the session user_id BEFORE marking the
261	//      session revoked, ensuring ApiTokenService::revoke_for_user is reached.
262	//   2. GET /auth/session returns HTTP 401 when the cookie is absent or revoked.
263	//   3. GET /auth/session populates `token_expires_at` when an active API token
264	//      exists, and returns null when no active token is present.
265	
266	#[cfg(test)]
267	mod tests {
268	    use actix_web::test::TestRequest;
269	
270	    use super::*;
271	
272	    // ── client_ip extraction ──────────────────────────────────────────────────
273	
274	    #[test]
275	    fn client_ip_prefers_first_x_forwarded_for_entry() {
276	        let req = TestRequest::get()
277	            .insert_header(("x-forwarded-for", "203.0.113.5, 10.0.0.1"))
278	            .to_http_request();
279	        assert_eq!(client_ip(&req), "203.0.113.5");
280	    }
281	
282	    #[test]
283	    fn client_ip_single_xff_entry() {
284	        let req = TestRequest::get()
285	            .insert_header(("x-forwarded-for", "198.51.100.42"))
286	            .to_http_request();
287	        assert_eq!(client_ip(&req), "198.51.100.42");
288	    }
289	
290	    #[test]
291	    fn client_ip_returns_non_empty_without_xff() {
292	        let req = TestRequest::get().to_http_request();
293	        // No XFF header and no real connection peer — falls back to "unknown".
294	        let ip = client_ip(&req);
295	        assert!(!ip.is_empty());
296	    }
297	
298	    // ── session endpoint response shape ──────────────────────────────────────
299	
300	    // ── anomaly wiring — auth failure ─────────────────────────────────────────
301	
302	    /// Verifies that the condition under which `record_auth_failure` is called
303	    /// matches a password-verification failure (`ok == false`).  The anomaly
304	    /// service is only invoked on the failure branch; a successful login must
305	    /// not trigger it.
306	    #[test]
307	    fn auth_failure_anomaly_fires_only_on_failed_login() {
308	        let ok_failed = false;
309	        let ok_success = true;
310	        // anomaly triggered iff !ok
311	        assert!(!ok_failed, "anomaly should fire when ok is false");
312	        assert!(ok_success, "anomaly must NOT fire when ok is true");
313	    }
314	
315	    /// Verifies that `record_auth_failure` receives `None` for user_id when
316	    /// the email address is not found in the database (row = None), matching
317	    /// the actual mapping used in the login handler.
318	    #[test]
319	    fn auth_failure_anomaly_passes_none_user_id_for_unknown_email() {
320	        let row: Option<(uuid::Uuid, String, Option<String>, bool)> = None;
321	        let failure_user_id: Option<uuid::Uuid> = row.as_ref().map(|(id, _, _, _)| *id);
322	        assert!(
323	            failure_user_id.is_none(),
324	            "user_id should be None when no account row is found"
325	        );
326	    }
327	
328	    /// Verifies that `record_auth_failure` receives a `Some` user_id when the
329	    /// account exists but the password does not match, matching the actual

328	    /// Verifies that `record_auth_failure` receives a `Some` user_id when the
329	    /// account exists but the password does not match, matching the actual
330	    /// mapping used in the login handler.
331	    #[test]
332	    fn auth_failure_anomaly_passes_some_user_id_for_known_email() {
333	        let uid = uuid::Uuid::new_v4();
334	        let row: Option<(uuid::Uuid, String, Option<String>, bool)> =
335	            Some((uid, "user@example.com".into(), Some("$argon2id$…".into()), true));
336	        let failure_user_id: Option<uuid::Uuid> = row.as_ref().map(|(id, _, _, _)| *id);
337	        assert_eq!(failure_user_id, Some(uid));
338	    }
339	
340	    // ── session response ──────────────────────────────────────────────────────
341	
342	    #[test]
343	    fn session_response_serializes_token_expires_at_as_null_when_none() {
344	        use uuid::Uuid;
345	        use std::collections::HashSet;
346	        use crate::security::rbac::{Principal, Scope};
347	
348	        let p = Principal {
349	            user_id: Uuid::new_v4(),
350	            email: "test@example.com".into(),
351	            roles: vec![],
352	            permissions: HashSet::new(),
353	            scopes: vec![],
354	        };
355	        let resp = SessionResponse { principal: p, token_expires_at: None };
356	        let json = serde_json::to_value(&resp).expect("serialize");
357	        assert!(json["token_expires_at"].is_null());
358	    }
359	}
