68	    // Load queue
69	    let load_queue = {
70	        let auth = auth.clone();
71	        let queue = queue.clone();
72	        let status_filter = status_filter.clone();
73	        Callback::from(move |_: ()| {
74	            let auth = auth.clone();
75	            let queue = queue.clone();
76	            let status_val = (*status_filter).clone();
77	            queue.set(None);
78	            spawn_local(async move {
79	                if let (Some(token), Some(key)) = (auth.api_token.clone(), auth.signing_key.clone()) {
80	                    let client = ApiClient { api_token: token, signing_key: key };
81	                    let url = format!("/api/v1/moderation/queue?status={}", status_val);
82	                    match client.get(&url).await {
83	                        Ok(r) if r.ok() => match r.json::<Vec<ModerationQueueItem>>().await {
84	                            Ok(v) => queue.set(Some(Ok(v))),
85	                            Err(e) => queue.set(Some(Err(e.to_string()))),
86	                        },
87	                        Ok(r) => queue.set(Some(Err(format!("HTTP {}", r.status())))),
88	                        Err(e) => queue.set(Some(Err(e))),
89	                    }
90	                }
91	            });
92	        })
93	    };
94	
95	    // Load policies
96	    let load_policies = {
97	        let auth = auth.clone();
98	        let policies = policies.clone();
99	        Callback::from(move |_: ()| {
100	            let auth = auth.clone();
101	            let policies = policies.clone();
102	            policies.set(None);
103	            spawn_local(async move {
104	                if let (Some(token), Some(key)) = (auth.api_token.clone(), auth.signing_key.clone()) {
105	                    let client = ApiClient { api_token: token, signing_key: key };
106	                    match client.get("/api/v1/moderation/policies").await {
107	                        Ok(r) if r.ok() => match r.json::<Vec<KeywordPolicy>>().await {
108	                            Ok(v) => policies.set(Some(Ok(v))),
109	                            Err(e) => policies.set(Some(Err(e.to_string()))),
110	                        },
111	                        Ok(r) => policies.set(Some(Err(format!("HTTP {}", r.status())))),
112	                        Err(e) => policies.set(Some(Err(e))),
113	                    }
114	                }
115	            });
116	        })
117	    };
118	
119	    // Initial load
120	    {
121	        let load_queue = load_queue.clone();
122	        let load_policies = load_policies.clone();
123	        use_effect_with((), move |_| {
124	            load_queue.emit(());
125	            load_policies.emit(());
126	            || ()
127	        });
128	    }
129	
130	    let review = {
131	        let auth = auth.clone();
132	        let action_msg = action_msg.clone();
133	        let load_queue = load_queue.clone();
134	        move |item_id: String, action: &'static str| {
135	            let auth = auth.clone();
136	            let action_msg = action_msg.clone();
137	            let load_queue = load_queue.clone();
138	            Callback::from(move |_: MouseEvent| {
139	                let auth = auth.clone();
140	                let item_id = item_id.clone();
141	                let action_msg = action_msg.clone();
142	                let load_queue = load_queue.clone();
143	                spawn_local(async move {
144	                    if let (Some(token), Some(key)) = (auth.api_token.clone(), auth.signing_key.clone()) {
145	                        let client = ApiClient { api_token: token, signing_key: key };
146	                        let url = format!("/api/v1/moderation/queue/{}/review", item_id);
147	                        let body = ReviewInput { action: action.to_string(), note: None };
148	                        match client.post_json(&url, &body).await {
149	                            Ok(r) if r.ok() => {
150	                                action_msg.set(Some(format!("Item {action}d.")));
151	                                load_queue.emit(());
152	                            }
153	                            Ok(r) => action_msg.set(Some(format!("Error: HTTP {}", r.status()))),
154	                            Err(e) => action_msg.set(Some(format!("Error: {e}"))),
155	                        }
156	                    }
157	                });
158	            })
159	        }
160	    };
161	
162	    let delete_policy = {
163	        let auth = auth.clone();
164	        let action_msg = action_msg.clone();
165	        let load_policies = load_policies.clone();
166	        move |policy_id: String| {
167	            let auth = auth.clone();
168	            let action_msg = action_msg.clone();
169	            let load_policies = load_policies.clone();
170	            Callback::from(move |_: MouseEvent| {
171	                let auth = auth.clone();
172	                let policy_id = policy_id.clone();
173	                let action_msg = action_msg.clone();
174	                let load_policies = load_policies.clone();
175	                spawn_local(async move {
176	                    if let (Some(token), Some(key)) = (auth.api_token.clone(), auth.signing_key.clone()) {
177	                        let client = ApiClient { api_token: token, signing_key: key };
178	                        let url = format!("/api/v1/moderation/policies/{}/delete", policy_id);
179	                        match client.post_json(&url, &serde_json::json!({})).await {
180	                            Ok(_) => {
181	                                action_msg.set(Some("Keyword policy deleted.".into()));
182	                                load_policies.emit(());
183	                            }
184	                            Err(e) => action_msg.set(Some(format!("Error: {e}"))),
185	                        }
186	                    }
187	                });
188	            })
189	        }
190	    };
191	
192	    let on_create_policy = {
193	        let auth = auth.clone();
194	        let new_keyword = new_keyword.clone();
195	        let new_severity = new_severity.clone();
196	        let action_msg = action_msg.clone();
197	        let load_policies = load_policies.clone();
198	        Callback::from(move |e: SubmitEvent| {
199	            e.prevent_default();
200	            let kw = (*new_keyword).clone();
201	            let sev = (*new_severity).clone();
202	            if kw.trim().is_empty() { return; }
203	            let auth = auth.clone();
204	            let action_msg = action_msg.clone();
205	            let load_policies = load_policies.clone();
