1	/// Security & Anomaly Events — admin view of detected anomalies.
2	/// Shows unacknowledged events first, allows acknowledgement.
3	use serde::Deserialize;
4	use wasm_bindgen_futures::spawn_local;
5	use yew::prelude::*;
6	
7	use crate::auth::{use_auth, ApiClient};
8	use crate::components::card::Card;
9	
10	#[derive(Clone, PartialEq, Deserialize, Debug)]
11	struct AnomalyEvent {
12	    id: String,
13	    rule_key: String,
14	    severity: String,
15	    subject_type: String,
16	    subject_value: String,
17	    detail: serde_json::Value,
18	    detected_at: String,
19	    acknowledged: bool,
20	    acknowledged_at: Option<String>,
21	}
22	
23	#[derive(Clone, PartialEq, Deserialize, Debug)]
24	struct AnomalyRule {
25	    rule_key: String,
26	    label: String,
27	    description: String,
28	    threshold_count: i32,
29	    window_seconds: i32,
30	    severity: String,
31	    is_active: bool,
32	}
33	
34	fn severity_badge(s: &str) -> Html {
35	    let (bg, fg) = match s {
36	        "critical" => ("#7f1d1d", "white"),
37	        "high" => ("#ef4444", "white"),
38	        "medium" => ("#f59e0b", "white"),
39	        _ => ("#6b7280", "white"),
40	    };
41	    html! {
42	        <span style={format!("background:{bg};color:{fg};padding:0.15rem 0.4rem;border-radius:3px;font-size:0.75rem;font-weight:bold;")}>
43	            {s.to_uppercase()}
44	        </span>
45	    }
46	}
47	
48	#[function_component(SecurityEventsPage)]
49	pub fn security_events() -> Html {
50	    let auth = use_auth();
51	    let show_all = use_state(|| false);
52	    let events = use_state(|| Option::<Result<Vec<AnomalyEvent>, String>>::None);
53	    let rules = use_state(|| Option::<Result<Vec<AnomalyRule>, String>>::None);
54	    let ack_msg = use_state(|| Option::<String>::None);
55	    let show_rules = use_state(|| false);
56	
57	    let load_events = {
58	        let auth = auth.clone();
59	        let events = events.clone();
60	        let show_all = show_all.clone();
61	        Callback::from(move |_: ()| {
62	            let auth = auth.clone();
63	            let events = events.clone();
64	            let unacked = !*show_all;
65	            events.set(None);
66	            spawn_local(async move {
67	                if let (Some(token), Some(key)) = (auth.api_token.clone(), auth.signing_key.clone()) {
68	                    let client = ApiClient { api_token: token, signing_key: key };
69	                    let url = format!("/api/v1/anomaly/events?unacked={}", unacked);
70	                    match client.get(&url).await {
71	                        Ok(r) if r.ok() => match r.json::<Vec<AnomalyEvent>>().await {
72	                            Ok(v) => events.set(Some(Ok(v))),
73	                            Err(e) => events.set(Some(Err(e.to_string()))),
74	                        },
75	                        Ok(r) => events.set(Some(Err(format!("HTTP {}", r.status())))),
76	                        Err(e) => events.set(Some(Err(e))),
77	                    }
78	                }
79	            });
80	        })
81	    };
82	
83	    // Load rules
84	    {
85	        let auth = auth.clone();
86	        let rules = rules.clone();
87	        use_effect_with((), move |_| {
88	            spawn_local(async move {
89	                if let (Some(token), Some(key)) = (auth.api_token.clone(), auth.signing_key.clone()) {
90	                    let client = ApiClient { api_token: token, signing_key: key };
91	                    match client.get("/api/v1/anomaly/rules").await {
92	                        Ok(r) if r.ok() => match r.json::<Vec<AnomalyRule>>().await {
93	                            Ok(v) => rules.set(Some(Ok(v))),
94	                            Err(e) => rules.set(Some(Err(e.to_string()))),
95	                        },
96	                        Ok(r) => rules.set(Some(Err(format!("HTTP {}", r.status())))),
97	                        Err(e) => rules.set(Some(Err(e))),
98	                    }
99	                }
100	            });
101	            || ()
102	        });
103	    }
104	
105	    // Initial events load
106	    {
107	        let load_events = load_events.clone();
108	        use_effect_with((), move |_| {
109	            load_events.emit(());
110	            || ()
111	        });
112	    }
113	
114	    let acknowledge = {
115	        let auth = auth.clone();
116	        let ack_msg = ack_msg.clone();
117	        let load_events = load_events.clone();
118	        move |event_id: String| {
119	            let auth = auth.clone();
120	            let ack_msg = ack_msg.clone();
121	            let load_events = load_events.clone();
122	            Callback::from(move |_: MouseEvent| {
123	                let auth = auth.clone();
124	                let event_id = event_id.clone();
125	                let ack_msg = ack_msg.clone();
126	                let load_events = load_events.clone();
127	                spawn_local(async move {
128	                    if let (Some(token), Some(key)) = (auth.api_token.clone(), auth.signing_key.clone()) {
129	                        let client = ApiClient { api_token: token, signing_key: key };
130	                        let url = format!("/api/v1/anomaly/events/{}/acknowledge", event_id);
131	                        match client.post_json(&url, &serde_json::json!({})).await {
132	                            Ok(r) if r.ok() => {
133	                                ack_msg.set(Some("Event acknowledged.".into()));
134	                                load_events.emit(());
135	                            }
136	                            Ok(r) => ack_msg.set(Some(format!("Error: HTTP {}", r.status()))),
137	                            Err(e) => ack_msg.set(Some(format!("Error: {e}"))),
138	                        }
139	                    }
140	                });
141	            })
142	        }
143	    };
144	
145	    let toggle_all = {
146	        let show_all = show_all.clone();
147	        let load_events = load_events.clone();
148	        Callback::from(move |_: MouseEvent| {
149	            show_all.set(!*show_all);
150	            load_events.emit(());
151	        })
152	    };
153	
154	    html! {
155	        <>
156	            <div class="page-header">
157	                <h1>{"Security & Anomaly Events"}</h1>
158	                <p>{"Rule-based anomaly detection events. Acknowledge and investigate suspicious activity."}</p>
159	            </div>
160	
161	            <Card>
162	                <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem;flex-wrap:wrap;gap:0.5rem;">
163	                    <div style="display:flex;gap:0.5rem;">
164	                        <button
165	                            class={if !*show_all { "button" } else { "button button--ghost" }}
166	                            onclick={Callback::from({let sa=show_all.clone(); let le=load_events.clone(); move |_| { sa.set(false); le.emit(()); }})}
167	                        >{"Unacknowledged"}</button>
168	                        <button
169	                            class={if *show_all { "button" } else { "button button--ghost" }}
170	                            onclick={toggle_all}
171	                        >{"All Events"}</button>
172	                    </div>
173	                    <button
174	                        class="button button--ghost"
175	                        onclick={Callback::from({let sr=show_rules.clone(); move |_| sr.set(!*sr)})}
176	                    >
177	                        {if *show_rules { "Hide Rules" } else { "Show Detection Rules" }}
178	                    </button>
179	                </div>
180	
181	                if let Some(ref msg) = *ack_msg {
182	                    <div style="margin-bottom:1rem;padding:0.5rem;background:#f0fff0;border-radius:4px;font-size:0.9rem;">
183	                        {msg}
184	                    </div>
185	                }
186	
187	                { match (*events).clone() {
188	                    None => html! { <div style="text-align:center;padding:2rem;color:#888;">{"Loading…"}</div> },
189	                    Some(Err(ref e)) => html! { <div style="color:red;padding:1rem;">{e}</div> },
190	                    Some(Ok(ref evts)) if evts.is_empty() => html! {
191	                        <div style="text-align:center;padding:2rem;color:#059669;">
192	                            <div style="font-size:2rem;">{"✓"}</div>
193	                            <div>{"No anomaly events to review."}</div>
194	                        </div>
195	                    },
196	                    Some(Ok(ref evts)) => html! {
197	                        <div style="overflow-x:auto;">
198	                        <table class="table" style="width:100%;">
199	                            <thead><tr>
200	                                <th>{"Severity"}</th><th>{"Rule"}</th>
201	                                <th>{"Subject"}</th><th>{"Detail"}</th>
202	                                <th>{"Detected"}</th><th>{"Status"}</th><th></th>
203	                            </tr></thead>
204	                            <tbody>
205	                            { for evts.iter().map(|ev| {
206	                                let ack_cb = acknowledge(ev.id.clone());
207	                                let detail_str = ev.detail.to_string();
208	                                html! { <tr>
209	                                    <td>{severity_badge(&ev.severity)}</td>
210	                                    <td style="font-size:0.85rem;max-width:200px;">
211	                                        <code style="font-size:0.75rem;">{&ev.rule_key}</code>
212	                                    </td>
213	                                    <td style="font-size:0.85rem;">
214	                                        <span style="color:#6b7280;">{format!("{}: ", ev.subject_type)}</span>
215	                                        <strong>{&ev.subject_value}</strong>
216	                                    </td>
217	                                    <td style="font-size:0.75rem;max-width:200px;overflow:hidden;text-overflow:ellipsis;color:#6b7280;">
218	                                        {detail_str}
219	                                    </td>
220	                                    <td style="font-size:0.8rem;white-space:nowrap;">
221	                                        {&ev.detected_at[..16]}
222	                                    </td>
223	                                    <td>
224	                                        if ev.acknowledged {
225	                                            <span style="color:#059669;font-size:0.8rem;">{"Acknowledged"}</span>
226	                                        } else {
227	                                            <span style="color:#ef4444;font-size:0.8rem;font-weight:bold;">{"Pending"}</span>
228	                                        }
229	                                    </td>
230	                                    <td>
231	                                        if !ev.acknowledged {
232	                                            <button class="button button--sm" onclick={ack_cb}>{"Acknowledge"}</button>
233	                                        }
234	                                    </td>
235	                                </tr> }
236	                            })}
237	                            </tbody>
238	                        </table>
239	                        </div>
240	                    },
241	                }}
242	
243	                // Detection rules panel
244	                if *show_rules {
245	                    <div style="margin-top:2rem;border-top:1px solid #eee;padding-top:1rem;">
246	                        <h3 style="margin-top:0;">{"Active Detection Rules"}</h3>
247	                        { match (*rules).clone() {
248	                            None | Some(Err(_)) => html! { <div style="color:#888;">{"Loading…"}</div> },
249	                            Some(Ok(ref rule_list)) => html! {
250	                                <table class="table" style="width:100%;">
251	                                    <thead><tr>
252	                                        <th>{"Rule"}</th><th>{"Description"}</th>
253	                                        <th>{"Threshold"}</th><th>{"Window"}</th><th>{"Severity"}</th>
254	                                    </tr></thead>
255	                                    <tbody>
256	                                    { for rule_list.iter().map(|r| html! {
257	                                        <tr>
258	                                            <td><code style="font-size:0.8rem;">{&r.rule_key}</code></td>
259	                                            <td style="font-size:0.85rem;">{&r.description}</td>
260	                                            <td>{format!("{} events", r.threshold_count)}</td>
261	                                            <td>{format!("{}s", r.window_seconds)}</td>
262	                                            <td>{severity_badge(&r.severity)}</td>
263	                                        </tr>
264	                                    })}
265	                                    </tbody>
266	                                </table>
267	                            },
268	                        }}
269	                    </div>
270	                }
271	            </Card>
272	        </>
273	    }
274	}
