1	use std::collections::{HashMap, VecDeque};
2	use std::sync::Arc;
3	use std::time::{Duration, Instant};
4	
5	use parking_lot::Mutex;
6	
7	use super::constants::rate_limit_per_min;
8	
9	/// Per-IP sliding-window rate limiter, in-process.
10	///
11	/// Limitation (documented in README): in a multi-replica deployment each
12	/// API container enforces its own window. The Task Prompt's offline-first
13	/// brief favors a single API container so this trade-off is acceptable;
14	/// upgrading to a shared store is a clean swap behind this struct.
15	#[derive(Clone)]
16	pub struct RateLimiter {
17	    inner: Arc<Mutex<HashMap<String, VecDeque<Instant>>>>,
18	    window: Duration,
19	    limit: usize,
20	}
21	
22	impl Default for RateLimiter {
23	    fn default() -> Self {
24	        Self {
25	            inner: Arc::new(Mutex::new(HashMap::new())),
26	            window: Duration::from_secs(60),
27	            limit: rate_limit_per_min() as usize,
28	        }
29	    }
30	}
31	
32	impl RateLimiter {
33	    /// Returns Ok(()) if the request is allowed, Err(retry_after_seconds)
34	    /// if it is rejected.
35	    pub fn check(&self, ip: &str) -> Result<(), u64> {
36	        let now = Instant::now();
37	        let mut map = self.inner.lock();
38	        let entry = map.entry(ip.to_string()).or_default();
39	        while let Some(front) = entry.front() {
40	            if now.duration_since(*front) > self.window {
41	                entry.pop_front();
42	            } else {
43	                break;
44	            }
45	        }
46	        if entry.len() >= self.limit {
47	            let oldest = *entry.front().expect("non-empty");
48	            let elapsed = now.duration_since(oldest);
49	            let retry = self.window.saturating_sub(elapsed).as_secs().max(1);
50	            return Err(retry);
51	        }
52	        entry.push_back(now);
53	        Ok(())
54	    }
55	}
