12	
13	/// Canonical string the client must sign:
14	///   METHOD\nPATH\nTIMESTAMP\nNONCE
15	///
16	/// PATH is always the bare resource path **without query string or fragment**
17	/// (e.g. `/api/v1/analytics/dashboard` regardless of any `?institution_id=…`
18	/// suffix).  Clients must strip the query before computing the canonical string.
19	///
20	/// The HMAC signing key is issued once at login (alongside the API token)
21	/// and held server-side in `api_tokens.signing_key`. The bearer token is
22	/// stored only as a SHA-256 hash so a DB leak alone does not yield usable
23	/// credentials. See `API_tests/README.md` for the full auth model.
24	pub struct RequestSigner;
25	
26	/// Return the signing path for a raw request URI, stripping any query string.
27	///
28	/// This is the single source of truth for the PATH component of the canonical
29	/// string: `signing_path("/api/v1/foo?bar=baz")` → `"/api/v1/foo"`.
30	/// Idempotent — safe to call on an already-stripped path.
31	pub fn signing_path(raw: &str) -> &str {
32	    // Everything before the first '?' is the path component.
33	    raw.split_once('?').map_or(raw, |(path, _)| path)
34	}
35	
36	impl RequestSigner {
37	    /// Canonical string used by `SignedAuth`. The HTTP body is intentionally
38	    /// excluded so the middleware can authenticate without consuming the
39	    /// payload — body integrity rides on the TLS channel terminated at the
40	    /// reverse proxy.
41	    ///
42	    /// The `path` argument MAY include a query string; it is stripped
43	    /// internally via `signing_path` so callers do not need to pre-strip.
44	    pub fn canonical_string_no_body(method: &str, path: &str, timestamp: &str, nonce: &str) -> String {
45	        format!("{}\n{}\n{}\n{}", method.to_uppercase(), signing_path(path), timestamp, nonce)
46	    }
47	
48	    pub fn sign(signing_key: &str, canonical: &str) -> String {
49	        let mut mac = HmacSha256::new_from_slice(signing_key.as_bytes()).expect("hmac key");
50	        mac.update(canonical.as_bytes());
51	        hex::encode(mac.finalize().into_bytes())
52	    }
53	
54	    pub fn verify(signing_key: &str, canonical: &str, provided_hex: &str) -> bool {
55	        let expected = Self::sign(signing_key, canonical);
56	        // constant-time-ish: compare via byte equality after length check
57	        if expected.len() != provided_hex.len() {
58	            return false;
59	        }
60	        let mut diff = 0u8;
61	        for (a, b) in expected.as_bytes().iter().zip(provided_hex.as_bytes().iter()) {
62	            diff |= a ^ b;
63	        }
64	        diff == 0
65	    }
66	}
