68	/// Parse RFC3339 *or* unix-seconds and return a UTC datetime.
69	pub fn parse_timestamp(value: &str) -> Result<DateTime<Utc>, ApiAppError> {
70	    if let Ok(secs) = value.parse::<i64>() {
71	        return DateTime::<Utc>::from_timestamp(secs, 0)
72	            .ok_or_else(|| ApiAppError::BadRequest("invalid timestamp".into()));
73	    }
74	    DateTime::parse_from_rfc3339(value)
75	        .map(|d| d.with_timezone(&Utc))
76	        .map_err(|_| ApiAppError::BadRequest("invalid timestamp".into()))
77	}
78	
79	pub fn within_replay_window(ts: DateTime<Utc>) -> bool {
80	    let now = Utc::now();
81	    let skew = Duration::from_std(REPLAY_WINDOW).unwrap();
82	    ts >= now - skew && ts <= now + skew
83	}
84	
85	/// Persist a request signature so a replay within the window is rejected.
86	/// Returns `Err(BadRequest("replay"))` if already seen.
87	pub async fn record_signature(pool: &PgPool, user_id: Uuid, signature: &str) -> Result<(), ApiAppError> {
88	    let expires_at = Utc::now() + Duration::from_std(REPLAY_WINDOW).unwrap() * 2;
89	    let res = sqlx::query(
90	        "INSERT INTO used_signatures (signature, user_id, expires_at) VALUES ($1, $2, $3)
91	         ON CONFLICT (signature) DO NOTHING",
92	    )
93	    .bind(signature)
94	    .bind(user_id)
95	    .bind(expires_at)
96	    .execute(pool)
97	    .await
98	    .map_err(|e| ApiAppError::Internal(e.to_string()))?;
99	    if res.rows_affected() == 0 {
100	        return Err(ApiAppError::BadRequest("replayed request signature".into()));
101	    }
102	    Ok(())
103	}
104	
105	/// Best-effort cleanup of expired entries; called by the worker but exposed
106	/// here so tests and admin endpoints can trigger it too.
107	pub async fn purge_expired_signatures(pool: &PgPool) -> Result<u64> {
108	    let res = sqlx::query("DELETE FROM used_signatures WHERE expires_at < NOW()")
109	        .execute(pool)
110	        .await?;
111	    Ok(res.rows_affected())
112	}
