23	    tracing_subscriber::fmt()
24	        .with_env_filter(EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")))
25	        .json()
26	        .init();
27	
28	    let cfg = AppConfig::load()?;
29	    tracing::info!(env = %cfg.environment, "starting backend-api");
30	
31	    let pool = infrastructure::db::connect(&cfg.database_url).await?;
32	
33	    if cfg.run_migrations {
34	        infrastructure::migrations::run(&pool).await?;
35	    }
36	    if cfg.run_seeds {
37	        infrastructure::seed::run(&pool).await?;
38	    }
39	
40	    let bind = (cfg.server.host.clone(), cfg.server.port);
41	    let pool_data = web::Data::new(pool);
42	    let limiter = RateLimiter::default();
43	
44	    tracing::info!(host = %bind.0, port = bind.1, "listening");
45	
46	    HttpServer::new(move || {
47	        App::new()
48	            .app_data(pool_data.clone())
49	            .wrap(IpGuard { limiter: limiter.clone() })
50	            .wrap(middleware::NormalizePath::trim())
51	            .wrap(middleware::Logger::default())
52	            .wrap(
53	                Cors::default()
54	                    // Allow the nginx proxy origin (port 8000) and direct frontend
55	                    // access (port 8081) used during local-network deployment and dev.
56	                    .allowed_origin("http://localhost:8000")
57	                    .allowed_origin("http://localhost:8081")
58	                    .allowed_origin("http://localhost:8080")
59	                    .allowed_methods(vec!["GET", "POST", "PUT", "PATCH", "DELETE"])
60	                    .allowed_headers(vec![
61	                        actix_web::http::header::CONTENT_TYPE,
62	                        actix_web::http::header::AUTHORIZATION,
63	                        // Custom signed-request headers
64	                        actix_web::http::header::HeaderName::from_static("x-silveroak-token"),
65	                        actix_web::http::header::HeaderName::from_static("x-silveroak-timestamp"),
66	                        actix_web::http::header::HeaderName::from_static("x-silveroak-nonce"),
67	                        actix_web::http::header::HeaderName::from_static("x-silveroak-signature"),
68	                    ])
69	                    .max_age(3600),
70	            )
71	            .configure(routes::configure)
72	    })
73	    .bind(bind)?
74	    .run()
75	    .await?;
76	
77	    Ok(())
78	}
