47	// IpGuard: blacklist + sliding-window rate limit
48	// =========================================================================
49	pub struct IpGuard {
50	    pub limiter: RateLimiter,
51	}
52	
53	impl<S, B> Transform<S, ServiceRequest> for IpGuard
54	where
55	    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error> + 'static,
56	    B: MessageBody + 'static,
57	{
58	    type Response = ServiceResponse<EitherBody<B, BoxBody>>;
59	    type Error = Error;
60	    type InitError = ();
61	    type Transform = IpGuardMw<S>;
62	    type Future = Ready<Result<Self::Transform, Self::InitError>>;
63	
64	    fn new_transform(&self, service: S) -> Self::Future {
65	        ready(Ok(IpGuardMw {
66	            service: Rc::new(service),
67	            limiter: self.limiter.clone(),
68	        }))
69	    }
70	}
71	
72	pub struct IpGuardMw<S> {
73	    service: Rc<S>,
74	    limiter: RateLimiter,
75	}
76	
77	impl<S, B> Service<ServiceRequest> for IpGuardMw<S>
78	where
79	    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error> + 'static,
80	    B: MessageBody + 'static,
81	{
82	    type Response = ServiceResponse<EitherBody<B, BoxBody>>;
83	    type Error = Error;
84	    type Future = LocalBoxFuture<'static, Result<Self::Response, Self::Error>>;
85	
86	    fn poll_ready(&self, cx: &mut std::task::Context<'_>) -> std::task::Poll<Result<(), Self::Error>> {
87	        self.service.poll_ready(cx)
88	    }
89	
90	    fn call(&self, req: ServiceRequest) -> Self::Future {
91	        let svc = self.service.clone();
92	        let limiter = self.limiter.clone();
93	        Box::pin(async move {
94	            let ip = client_ip(&req);
95	            req.extensions_mut().insert(ClientIp(ip.clone()));
96	
97	            if let Some(pool) = req.app_data::<web::Data<PgPool>>().cloned() {
98	                if blacklist::is_blacklisted(pool.get_ref(), &ip).await.unwrap_or(false) {
99	                    let resp = ApiAppError::Forbidden("ip blacklisted".into()).error_response();
100	                    return Ok(req.into_response(resp).map_into_right_body());
101	                }
102	            }
103	            if let Err(retry) = limiter.check(&ip) {
104	                let resp = ApiAppError::RateLimited(retry).error_response();
105	                return Ok(req.into_response(resp).map_into_right_body());
106	            }
107	            svc.call(req).await.map(|r| r.map_into_left_body())
108	        })
109	    }
110	}
