112	// =========================================================================
113	// SignedAuth: token + HMAC signature + ±60s replay window + nonce store
114	// =========================================================================
115	//
116	// Canonical string signed by the client (body excluded so the middleware
117	// does not need to consume the request body — body integrity already
118	// rides on the TLS channel from the reverse proxy):
119	//
120	//     METHOD \n PATH \n TIMESTAMP \n NONCE
121	//
122	// The HMAC key is the per-token `signing_key` returned at login.
123	// The signature is also stored in `used_signatures` with TTL so the same
124	// (token, nonce, timestamp) tuple cannot be replayed inside the window.
125	pub struct SignedAuth;
126	
127	impl<S, B> Transform<S, ServiceRequest> for SignedAuth
128	where
129	    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error> + 'static,
130	    B: MessageBody + 'static,
131	{
132	    type Response = ServiceResponse<EitherBody<B, BoxBody>>;
133	    type Error = Error;
134	    type InitError = ();
135	    type Transform = SignedAuthMw<S>;
136	    type Future = Ready<Result<Self::Transform, Self::InitError>>;
137	
138	    fn new_transform(&self, service: S) -> Self::Future {
139	        ready(Ok(SignedAuthMw { service: Rc::new(service) }))
140	    }
141	}
142	
143	pub struct SignedAuthMw<S> { service: Rc<S> }
144	
145	impl<S, B> Service<ServiceRequest> for SignedAuthMw<S>
146	where
147	    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error> + 'static,
148	    B: MessageBody + 'static,
149	{
150	    type Response = ServiceResponse<EitherBody<B, BoxBody>>;
151	    type Error = Error;
152	    type Future = LocalBoxFuture<'static, Result<Self::Response, Self::Error>>;
153	
154	    fn poll_ready(&self, cx: &mut std::task::Context<'_>) -> std::task::Poll<Result<(), Self::Error>> {
155	        self.service.poll_ready(cx)
156	    }
157	
158	    fn call(&self, req: ServiceRequest) -> Self::Future {
159	        let svc = self.service.clone();
160	        Box::pin(async move {
161	            let reject = |err: ApiAppError, req: ServiceRequest| {
162	                Ok::<_, Error>(req.into_response(err.error_response()).map_into_right_body())
163	            };
164	
165	            let Some(token) = header(&req, HDR_API_TOKEN) else {
166	                return reject(ApiAppError::Unauthorized("missing api token".into()), req);
167	            };
168	            let Some(ts) = header(&req, HDR_TIMESTAMP) else {
169	                return reject(ApiAppError::Unauthorized("missing timestamp".into()), req);
170	            };
171	            let Some(nonce) = header(&req, HDR_NONCE) else {
172	                return reject(ApiAppError::Unauthorized("missing nonce".into()), req);
173	            };
174	            let Some(sig) = header(&req, HDR_SIGNATURE) else {
175	                return reject(ApiAppError::Unauthorized("missing signature".into()), req);
176	            };
177	
178	            let ts_parsed = match signing::parse_timestamp(&ts) {
179	                Ok(v) => v,
180	                Err(e) => return reject(e, req),
181	            };
182	            if !signing::within_replay_window(ts_parsed) {
183	                return reject(
184	                    ApiAppError::Unauthorized("timestamp outside replay window".into()),
185	                    req,
186	                );
187	            }
188	
189	            let pool = req
190	                .app_data::<web::Data<PgPool>>()
191	                .cloned()
192	                .expect("pg pool present");
193	
194	            let ctx = match ApiTokenService::lookup(pool.get_ref(), &token).await {
195	                Ok(Some(c)) => c,
196	                Ok(None) => {
197	                    return reject(
198	                        ApiAppError::Unauthorized("invalid or expired token".into()),
199	                        req,
200	                    )
201	                }
202	                Err(e) => return reject(ApiAppError::Internal(e.to_string()), req),
203	            };
204	
205	            // Normalized canonical: PATH is always query-stripped.
206	            // `canonical_string_no_body` applies `signing_path` internally, but
207	            // we pass `req.uri().path()` (already stripped by Actix) to be
208	            // explicit about the contract.
209	            let canonical = signing::RequestSigner::canonical_string_no_body(
210	                req.method().as_str(),
211	                req.uri().path(),
212	                &ts,
213	                &nonce,
214	            );
215	            let mut verified = signing::RequestSigner::verify(&ctx.signing_key, &canonical, &sig);
216	
217	            // TODO(compat): Remove this legacy fallback once all clients have been
218	            // updated to strip query strings before signing (see client.rs fix and
219	            // API_tests/README.md for the canonical-string contract).  The old Yew
220	            // frontend included the full path+query in the canonical string, which
221	            // caused every query-bearing GET to return 401.  During the transition
222	            // window we also try the query-included form so older clients can
223	            // continue to operate.  The two forms can never collide: when there is
224	            // no query string both canonicals are identical and the first verify
225	            // already passed, so this branch is only reached for query-bearing
226	            // requests that failed normalized verification.
227	            if !verified {
228	                if let Some(pq) = req.uri().path_and_query().map(|pq| pq.as_str()) {
229	                    if pq != req.uri().path() {
230	                        let legacy = format!(
231	                            "{}\n{}\n{}\n{}",
232	                            req.method().as_str().to_uppercase(),
233	                            pq,
234	                            ts,
235	                            nonce,
236	                        );
237	                        verified =
238	                            signing::RequestSigner::verify(&ctx.signing_key, &legacy, &sig);
239	                    }
240	                }
241	            }
242	
243	            if !verified {
244	                return reject(ApiAppError::Unauthorized("bad signature".into()), req);
245	            }
246	
247	            if let Err(e) = signing::record_signature(pool.get_ref(), ctx.user_id, &sig).await {
248	                return reject(e, req);
249	            }
250	
251	            let principal = match rbac::load_principal(pool.get_ref(), ctx.user_id).await {
252	                Ok(p) => p,
253	                Err(e) => return reject(ApiAppError::Internal(e.to_string()), req),
254	            };
255	
256	            // Capture what we need for post-response anomaly recording before
257	            // `req` is moved into `svc.call`.
258	            let user_id_for_recording = principal.user_id;
259	            let path_for_recording = req.uri().path().to_string();
260	            let pool_for_recording = pool.clone();
261	
262	            req.extensions_mut().insert(principal);
263	
264	            let result = svc.call(req).await.map(|r| r.map_into_left_body());
265	
266	            // Post-process: if the handler returned HTTP 403 Forbidden, record
267	            // a permission-denial signal for anomaly detection.  This is
268	            // fire-and-forget — a recording failure must never overwrite or mask
269	            // the real 403 that the handler already decided to return.
270	            if let Ok(ref resp) = result {
271	                if resp.status() == actix_web::http::StatusCode::FORBIDDEN {
272	                    if let Err(e) = crate::anomaly::service::record_permission_denial(
273	                        pool_for_recording.get_ref(),
274	                        user_id_for_recording,
275	                        "forbidden_request",
276	                        &path_for_recording,
277	                    )
278	                    .await
279	                    {
280	                        tracing::warn!(
281	                            user_id = %user_id_for_recording,
282	                            path = %path_for_recording,
283	                            err = %e,
284	                            "anomaly: permission denial recording failed"
285	                        );
286	                    }
287	                }
288	            }
289	
290	            result
291	        })
292	    }
293	}
