63	        let rl = RateLimiter::default();
64	        for _ in 0..rate_limit_per_min() {
65	            assert!(rl.check("1.2.3.4").is_ok());
66	        }
67	        assert!(rl.check("1.2.3.4").is_err());
68	        // different IP not affected
69	        assert!(rl.check("9.9.9.9").is_ok());
