165	            RequestSigner::canonical_string_no_body("GET", "/test", "123", "n");
166	        let sig1 = RequestSigner::sign("key-one", &canon);
167	        let sig2 = RequestSigner::sign("key-two", &canon);
168	        assert_ne!(sig1, sig2);
169	    }
