171	    // ── signing_path ──────────────────────────────────────────────────────────
172	
173	    #[test]
174	    fn signing_path_strips_query_string() {
175	        assert_eq!(
176	            signing_path("/api/v1/analytics/dashboard?institution_id=abc"),
177	            "/api/v1/analytics/dashboard"
178	        );
179	    }
180	
181	    #[test]
182	    fn signing_path_strips_multi_param_query() {
183	        assert_eq!(
184	            signing_path("/api/v1/analytics/daily?institution_id=abc&date=2024-01-01"),
185	            "/api/v1/analytics/daily"
186	        );
187	    }
188	
189	    #[test]
190	    fn signing_path_no_query_unchanged() {
191	        assert_eq!(signing_path("/api/v1/family/groups"), "/api/v1/family/groups");
192	    }
193	
194	    #[test]
195	    fn signing_path_is_idempotent() {
196	        let p = "/api/v1/test";
197	        assert_eq!(signing_path(signing_path(p)), p);
198	    }
199	
200	    // ── canonical_string_no_body with query paths ─────────────────────────────
201	
202	    #[test]
203	    fn canonical_with_query_path_equals_canonical_with_stripped_path() {
204	        // A caller that passes the full path+query gets the same canonical as one
205	        // that pre-strips.  This is what makes the server-side verification correct
206	        // regardless of how the URI arrives in the middleware.
207	        let ts = "1700000000";
208	        let nonce = "n42";
209	        let with_query =
210	            RequestSigner::canonical_string_no_body("GET", "/api/v1/foo?bar=baz", ts, nonce);
211	        let stripped =
212	            RequestSigner::canonical_string_no_body("GET", "/api/v1/foo", ts, nonce);
213	        assert_eq!(with_query, stripped);
214	    }
215	
216	    #[test]
217	    fn canonical_no_query_path_has_four_newline_parts() {
218	        let c = RequestSigner::canonical_string_no_body(
219	            "GET", "/api/v1/analytics/dashboard?institution_id=xyz", "1700000000", "nonce-abc",
220	        );
221	        let parts: Vec<&str> = c.split('\n').collect();
222	        assert_eq!(parts.len(), 4);
223	        assert_eq!(parts[0], "GET");
224	        // PATH component must never contain a query string.
225	        assert_eq!(parts[1], "/api/v1/analytics/dashboard");
226	        assert!(!parts[1].contains('?'), "signing path must not contain query string");
227	        assert_eq!(parts[2], "1700000000");
228	        assert_eq!(parts[3], "nonce-abc");
229	    }
