231	    #[test]
232	    fn replay_protection_not_affected_by_query_stripping() {
233	        // Two requests to the same endpoint with different query strings but the
234	        // same method, timestamp and nonce WOULD produce the same canonical —
235	        // and therefore the same signature.  The replay window (timestamp + nonce
236	        // uniqueness) is the real replay guard; query params are not part of the
237	        // signed surface.  This test documents the intentional design.
238	        let c1 = RequestSigner::canonical_string_no_body(
239	            "GET", "/api/v1/foo?a=1", "1700000000", "n1",
240	        );
241	        let c2 = RequestSigner::canonical_string_no_body(
242	            "GET", "/api/v1/foo?a=2", "1700000000", "n1",
243	        );
244	        // Same canonical → same signature (query string is not signed).
245	        assert_eq!(c1, c2);
246	    }
