21	async fn main() -> Result<()> {
22	    let _ = dotenvy::dotenv();
23	    tracing_subscriber::fmt()
24	        .with_env_filter(EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")))
25	        .json()
26	        .init();
