35	    }
36	    if cfg.run_seeds {
37	        infrastructure::seed::run(&pool).await?;
38	    }
39	
40	    let bind = (cfg.server.host.clone(), cfg.server.port);
41	    let pool_data = web::Data::new(pool);
42	    let limiter = RateLimiter::default();
43	
44	    tracing::info!(host = %bind.0, port = bind.1, "listening");
45	
46	    HttpServer::new(move || {
47	        App::new()
48	            .app_data(pool_data.clone())
49	            .wrap(IpGuard { limiter: limiter.clone() })
50	            .wrap(middleware::NormalizePath::trim())
51	            .wrap(middleware::Logger::default())
