56	                    .allowed_origin("http://localhost:8000")
57	                    .allowed_origin("http://localhost:8081")
58	                    .allowed_origin("http://localhost:8080")
59	                    .allowed_methods(vec!["GET", "POST", "PUT", "PATCH", "DELETE"])
60	                    .allowed_headers(vec![
61	                        actix_web::http::header::CONTENT_TYPE,
62	                        actix_web::http::header::AUTHORIZATION,
63	                        // Custom signed-request headers
64	                        actix_web::http::header::HeaderName::from_static("x-silveroak-token"),
65	                        actix_web::http::header::HeaderName::from_static("x-silveroak-timestamp"),
66	                        actix_web::http::header::HeaderName::from_static("x-silveroak-nonce"),
67	                        actix_web::http::header::HeaderName::from_static("x-silveroak-signature"),
68	                    ])
