{"file_path": "/home/nahom/Desktop/Others/EaglePointAI/vibe-coding-projects/week-2/SilverOak/TASK-17/repo/apps/backend-api/src/security/rate_limit.rs", "content": "//! Pluggable per-IP sliding-window rate limiter.
//!
//! Two backends are available:
//!
//! * **Memory** (`APP__RATE_LIMIT_BACKEND=memory`, default) — process-local
//!   `HashMap<ip, VecDeque<Instant>>` protected by a `parking_lot::Mutex`.
//!   Fast and zero-dependency, but each API replica enforces its own window.
//!   Suitable for single-container deployments (the project's offline-first
//!   brief) or dev environments.
//!
//! * **Postgres** (`APP__RATE_LIMIT_BACKEND=postgres`) — timestamps are stored
//!   in the `rate_limit_log` table (migration 0008).  Every replica shares the
//!   same sliding window, making this correct under horizontal scaling.
//!   Slightly higher latency (~1 extra DB round-trip per request).
//!
//! The active backend is selected at startup; switching requires a restart.
//! The `RateLimiter::check` method is `async` so that both backends share the
//! same call site in `IpGuardMw`.

use std::collections::{HashMap, VecDeque};
use std::sync::Arc;
use std::time::{Duration, Instant};

use parking_lot::Mutex;
use sqlx::PgPool;

use super::constants::rate_limit_per_min;

// ── in-memory backend ─────────────────────────────────────────────────────────

/// Process-local sliding-window limiter.  See module-level docs.
#[derive(Clone)]
pub struct InMemoryLimiter {
    inner: Arc<Mutex<HashMap<String, VecDeque<Instant>>>>,
    window: Duration,
    limit: usize,
}

impl Default for InMemoryLimiter {
    fn default() -> Self {
        Self {
            inner: Arc::new(Mutex::new(HashMap::new())),
            window: Duration::from_secs(60),
            limit: rate_limit_per_min() as usize,
        }
    }
}

impl InMemoryLimiter {
    fn check(&self, ip: &str) -> Result<(), u64> {
        let now = Instant::now();
        let mut map = self.inner.lock();
        let entry = map.entry(ip.to_string()).or_default();
        while let Some(front) = entry.front() {
            if now.duration_since(*front) > self.window {
                entry.pop_front();
            } else {
                break;
            }
        }
        if entry.len() >= self.limit {
            let oldest = *entry.front().expect("non-empty");
            let elapsed = now.duration_since(oldest);
            let retry = self.window.saturating_sub(elapsed).as_secs().max(1);
            return Err(retry);
        }
        entry.push_back(now);
        Ok(())
    }
}

// ── postgres backend ──────────────────────────────────────────────────────────

/// Distributed sliding-window limiter backed by the `rate_limit_log` table.
/// Requires migration 0008.  See module-level docs.
#[derive(Clone)]
pub struct PostgresLimiter {
    pool: PgPool,
    window_secs: i64,
    limit: i64,
}

impl PostgresLimiter {
    pub fn new(pool: PgPool) -> Self {
        Self {
            pool,
            window_secs: 60,
            limit: rate_limit_per_min() as i64,
        }
    }

    async fn check(&self, ip: &str) -> Result<(), u64> {
        // 1. Purge expired entries for this IP.
        sqlx::query(
            "DELETE FROM rate_limit_log WHERE ip = $1 AND ts < NOW() - ($2 || ' seconds')::INTERVAL",
        )
        .bind(ip)
        .bind(self.window_secs)
        .execute(&self.pool)
        .await
        .ok(); // best-effort purge; failure does not stop the check

        // 2. Count remaining entries in the window.
        let count: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM rate_limit_log WHERE ip = $1",
        )
        .bind(ip)
        .fetch_one(&self.pool)
        .await
        .unwrap_or(0);

        if count >= self.limit {
            // Estimate retry-after from the oldest entry.
            let oldest_ts: Option<chrono::DateTime<chrono::Utc>> =
                sqlx::query_scalar("SELECT MIN(ts) FROM rate_limit_log WHERE ip = $1")
                    .bind(ip)
                    .fetch_optional(&self.pool)
                    .await
                    .ok()
                    .flatten();

            let retry = oldest_ts
                .map(|t| {
                    let window_end = t + chrono::Duration::seconds(self.window_secs);
                    let now = chrono::Utc::now();
                    if window_end > now {
                        (window_end - now).num_seconds().max(1) as u64
                    } else {
                        1
                    }
                })
                .unwrap_or(1);

            return Err(retry);
        }

        // 3. Record this request.
        sqlx::query("INSERT INTO rate_limit_log (ip) VALUES ($1)")
            .bind(ip)
            .execute(&self.pool)
            .await
            .ok(); // best-effort; a failed insert means we under-count (safe)

        Ok(())
    }
}

// ── unified enum ─────────────────────────────────────────────────────────────

/// Active rate-limiter backend.  Constructed once at startup from
/// `AppConfig::rate_limit_backend` and passed to `IpGuard`.
#[derive(Clone)]
pub enum RateLimiter {
    Memory(InMemoryLimiter),
    Postgres(PostgresLimiter),
}

impl Default for RateLimiter {
    /// Defaults to the in-memory backend for backward compatibility.
    fn default() -> Self {
        Self::Memory(InMemoryLimiter::default())
    }
}

impl RateLimiter {
    /// Construct the appropriate backend from a configuration string.
    /// Accepts `"postgres"` (case-insensitive) for the Postgres backend;
    /// any other value uses the in-memory backend.
    pub fn from_config(backend: &str, pool: Option<PgPool>) -> Self {
        if backend.eq_ignore_ascii_case("postgres") {
            if let Some(p) = pool {
                return Self::Postgres(PostgresLimiter::new(p));
            }
            tracing::warn!(
                "rate_limit_backend=postgres but no pool supplied; \
                 falling back to memory"
            );
        }
        Self::Memory(InMemoryLimiter::default())
    }

    /// Returns `Ok(())` if the request is allowed, `Err(retry_after_seconds)`
    /// if the sliding window is full.
    pub async fn check(&self, ip: &str) -> Result<(), u64> {
        match self {
            Self::Memory(m) => m.check(ip),
            Self::Postgres(p) => p.check(ip).await,
        }
    }
}

// ── tests ─────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    fn memory_limiter() -> RateLimiter {
        RateLimiter::Memory(InMemoryLimiter::default())
    }

    #[tokio::test]
    async fn allows_up_to_limit_then_rejects() {
        let rl = memory_limiter();
        for _ in 0..rate_limit_per_min() {
            assert!(rl.check("1.2.3.4").await.is_ok());
        }
        assert!(rl.check("1.2.3.4").await.is_err());
        // different IP not affected
        assert!(rl.check("9.9.9.9").await.is_ok());
    }

    #[tokio::test]
    async fn multiple_ips_are_independent() {
        let rl = memory_limiter();
        for _ in 0..rate_limit_per_min() {
            rl.check("10.0.0.1").await.ok();
        }
        assert!(rl.check("10.0.0.1").await.is_err());
        // a different IP starts with a fresh window
        assert!(rl.check("10.0.0.2").await.is_ok());
    }

    #[tokio::test]
    async fn fresh_ip_is_allowed() {
        let rl = memory_limiter();
        assert!(rl.check("brand-new-ip").await.is_ok());
    }

    #[tokio::test]
    async fn rejection_returns_retry_after_seconds() {
        let rl = memory_limiter();
        for _ in 0..rate_limit_per_min() {
            rl.check("ip-x").await.ok();
        }
        let err = rl.check("ip-x").await.unwrap_err();
        assert!(err >= 1, "retry-after must be at least 1 second");
    }

    /// Verifies that `from_config("memory", None)` yields a Memory variant.
    #[test]
    fn from_config_memory_variant() {
        let rl = RateLimiter::from_config("memory", None);
        assert!(matches!(rl, RateLimiter::Memory(_)));
    }

    /// Verifies that `from_config("postgres", None)` falls back to Memory
    /// when no pool is provided (the pool is unavailable in unit tests).
    #[test]
    fn from_config_postgres_without_pool_falls_back_to_memory() {
        let rl = RateLimiter::from_config("postgres", None);
        assert!(
            matches!(rl, RateLimiter::Memory(_)),
            "should fall back to memory when no pool is supplied"
        );
    }

    /// Verifies that an unknown backend name also yields a Memory variant.
    #[test]
    fn from_config_unknown_backend_yields_memory() {
        let rl = RateLimiter::from_config("redis", None);
        assert!(matches!(rl, RateLimiter::Memory(_)));
    }
}
"}

