        // Mirror the extraction logic from `client_ip()` to test it in isolation.
        let ip = req
            .headers()
            .get("x-forwarded-for")
            .and_then(|h| h.to_str().ok())
            .and_then(|v| v.split(',').next())
            .map(|s| s.trim().to_string())
            .unwrap_or_default();
        assert_eq!(ip, "10.0.0.1");
    }

    // ── strict-signing mode ───────────────────────────────────────────────────

    /// Confirms that `SignedAuth::default()` has `strict = false` — no existing
    /// deployments should see a behavior change unless they explicitly opt in.
    #[test]
    fn signed_auth_defaults_to_non_strict() {
        let sa = super::SignedAuth::default();
        assert!(
            !sa.strict,
            "strict_signing must default to false to preserve backward compatibility"
        );
    }

    /// Confirms the body-hash header name constant is correct — a typo here
    /// would make strict-mode verification silently always fail.
    #[test]
    fn body_hash_header_name_matches_constant() {
        assert_eq!(
            super::super::constants::HDR_BODY_HASH,
            "x-silveroak-body-hash",
        );
    }

    /// Confirms that a strict-mode canonical with a known body hash verifies
    /// correctly and a tampered hash does not — end-to-end check of the
    /// strict signing path without needing a live DB.
    #[test]
    fn strict_mode_signature_verifies_with_correct_body_hash() {
        use crate::security::signing::RequestSigner;

        let key = "test-signing-key";
        let body_hash = RequestSigner::sha256_hex(b"{\"foo\":1}");
        let canonical = RequestSigner::canonical_string_strict(
            "POST",
            "/api/v1/requisitions?draft=true",
            "1700000000",
            "nonce42",
            &body_hash,
        );
        let sig = RequestSigner::sign(key, &canonical);

        // Correct hash → valid
        assert!(RequestSigner::verify(key, &canonical, &sig));

        // Tampered body hash → invalid
        let bad_hash = RequestSigner::sha256_hex(b"tampered");
        let bad_canonical = RequestSigner::canonical_string_strict(
            "POST",
            "/api/v1/requisitions?draft=true",
            "1700000000",
            "nonce42",
            &bad_hash,
        );
        assert!(!RequestSigner::verify(key, &bad_canonical, &sig));
    }
}"}

