116	// =========================================================================
117	// SignedAuth: token + HMAC signature + ±60s replay window + nonce store
118	// =========================================================================
119	//
120	// Standard canonical string (body excluded — body integrity rides on TLS):
121	//
122	//     METHOD \n PATH \n TIMESTAMP \n NONCE
123	//
124	// Strict-mode canonical string (when `strict = true`):
125	//
126	//     METHOD \n PATH \n TIMESTAMP \n NONCE \n QUERY \n BODY_SHA256
127	//
128	// where BODY_SHA256 is supplied by the client in the `x-silveroak-body-hash`
129	// header.  Strict mode defaults to `false` for backward compatibility.
130	//
131	// The HMAC key is the per-token `signing_key` returned at login.
132	// The signature is also stored in `used_signatures` with TTL so the same
133	// (token, nonce, timestamp) tuple cannot be replayed inside the window.
134	pub struct SignedAuth {
135	    /// When `true`, verifies the 6-field strict canonical that includes the
136	    /// query string and client-supplied body hash.  Set from
137	    /// `AppConfig::strict_signing`.  Defaults to `false`.
138	    pub strict: bool,
139	}
140	
141	impl Default for SignedAuth {
142	    fn default() -> Self {
143	        Self { strict: false }
144	    }
145	}
146	
147	impl<S, B> Transform<S, ServiceRequest> for SignedAuth
148	where
149	    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error> + 'static,
150	    B: MessageBody + 'static,
151	{
152	    type Response = ServiceResponse<EitherBody<B, BoxBody>>;
153	    type Error = Error;
154	    type InitError = ();
155	    type Transform = SignedAuthMw<S>;
156	    type Future = Ready<Result<Self::Transform, Self::InitError>>;
157	
158	    fn new_transform(&self, service: S) -> Self::Future {
159	        ready(Ok(SignedAuthMw { service: Rc::new(service), strict: self.strict }))
160	    }
161	}
162	
163	pub struct SignedAuthMw<S> {
164	    service: Rc<S>,
165	    strict: bool,
166	}
167	
168	impl<S, B> Service<ServiceRequest> for SignedAuthMw<S>
169	where
170	    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error> + 'static,
171	    B: MessageBody + 'static,

183	        let strict = self.strict;
184	        Box::pin(async move {
185	            let reject = |err: ApiAppError, req: ServiceRequest| {
186	                Ok::<_, Error>(req.into_response(err.error_response()).map_into_right_body())
187	            };
188	
189	            let Some(token) = header(&req, HDR_API_TOKEN) else {
