1	//! Pluggable per-IP sliding-window rate limiter.
2	//!
3	//! Two backends are available:
4	//!
5	//! * **Memory** (`APP__RATE_LIMIT_BACKEND=memory`, default) — process-local
6	//!   `HashMap<ip, VecDeque<Instant>>` protected by a `parking_lot::Mutex`.
7	//!   Fast and zero-dependency, but each API replica enforces its own window.
8	//!   Suitable for single-container deployments (the project's offline-first
9	//!   brief) or dev environments.
10	//!
11	//! * **Postgres** (`APP__RATE_LIMIT_BACKEND=postgres`) — timestamps are stored
12	//!   in the `rate_limit_log` table (migration 0008).  Every replica shares the
13	//!   same sliding window, making this correct under horizontal scaling.
14	//!   Slightly higher latency (~1 extra DB round-trip per request).
15	//!
16	//! The active backend is selected at startup; switching requires a restart.
17	//! The `RateLimiter::check` method is `async` so that both backends share the
18	//! same call site in `IpGuardMw`.
19	
20	use std::collections::{HashMap, VecDeque};
21	use std::sync::Arc;
22	use std::time::{Duration, Instant};
23	
24	use chrono::Utc;
25	use parking_lot::Mutex;
26	use sqlx::PgPool;
27	
28	use super::constants::rate_limit_per_min;
29	
30	// ── in-memory backend ─────────────────────────────────────────────────────────
31	
32	/// Process-local sliding-window limiter.  See module-level docs.
33	#[derive(Clone)]
34	pub struct InMemoryLimiter {
35	    inner: Arc<Mutex<HashMap<String, VecDeque<Instant>>>>,
36	    window: Duration,
37	    limit: usize,
38	}
39	
40	impl Default for InMemoryLimiter {
41	    fn default() -> Self {
42	        Self {
43	            inner: Arc::new(Mutex::new(HashMap::new())),
44	            window: Duration::from_secs(60),
45	            limit: rate_limit_per_min() as usize,
46	        }
47	    }
48	}
49	
50	impl InMemoryLimiter {
51	    fn check(&self, ip: &str) -> Result<(), u64> {
52	        let now = Instant::now();
53	        let mut map = self.inner.lock();
54	        let entry = map.entry(ip.to_string()).or_default();
55	        while let Some(front) = entry.front() {
56	            if now.duration_since(*front) > self.window {
57	                entry.pop_front();
58	            } else {
59	                break;
60	            }
61	        }
62	        if entry.len() >= self.limit {
63	            let oldest = *entry.front().expect("non-empty");
64	            let elapsed = now.duration_since(oldest);
65	            let retry = self.window.saturating_sub(elapsed).as_secs().max(1);
66	            return Err(retry);
67	        }
68	        entry.push_back(now);
69	        Ok(())
70	    }
71	}
72	
73	// ── postgres backend ──────────────────────────────────────────────────────────
74	
75	/// Distributed sliding-window limiter backed by the `rate_limit_log` table.
76	/// Requires migration 0008.  See module-level docs.
77	#[derive(Clone)]
78	pub struct PostgresLimiter {
79	    pool: PgPool,
80	    window_secs: i64,
81	    limit: i64,
82	}
83	
84	impl PostgresLimiter {
85	    pub fn new(pool: PgPool) -> Self {
86	        Self {
87	            pool,
88	            window_secs: 60,
89	            limit: rate_limit_per_min() as i64,
90	        }
91	    }
92	
93	    async fn check(&self, ip: &str) -> Result<(), u64> {
94	        // 1. Purge expired entries for this IP.
95	        sqlx::query(
96	            "DELETE FROM rate_limit_log WHERE ip = $1 AND ts < NOW() - ($2 || ' seconds')::INTERVAL",
97	        )
98	        .bind(ip)
99	        .bind(self.window_secs)
100	        .execute(&self.pool)
101	        .await
102	        .ok(); // best-effort purge; failure does not stop the check
103	
104	        // 2. Count remaining entries in the window.
105	        let count: i64 = sqlx::query_scalar(
106	            "SELECT COUNT(*) FROM rate_limit_log WHERE ip = $1",
107	        )
108	        .bind(ip)
109	        .fetch_one(&self.pool)
110	        .await
111	        .unwrap_or(0);
112	
113	        if count >= self.limit {
114	            // Estimate retry-after from the oldest entry.
115	            let oldest_ts: Option<chrono::DateTime<Utc>> =
116	                sqlx::query_scalar("SELECT MIN(ts) FROM rate_limit_log WHERE ip = $1")
117	                    .bind(ip)
118	                    .fetch_optional(&self.pool)
119	                    .await
120	                    .ok()
121	                    .flatten();
122	
123	            let retry = oldest_ts
124	                .map(|t| {
125	                    let window_end = t + chrono::Duration::seconds(self.window_secs);
126	                    let now = Utc::now();
127	                    if window_end > now {
128	                        (window_end - now).num_seconds().max(1) as u64
129	                    } else {
130	                        1
131	                    }
132	                })
133	                .unwrap_or(1);
134	
135	            return Err(retry);
136	        }
137	
138	        // 3. Record this request.
139	        sqlx::query("INSERT INTO rate_limit_log (ip) VALUES ($1)")
140	            .bind(ip)
141	            .execute(&self.pool)
142	            .await
143	            .ok(); // best-effort; a failed insert means we under-count (safe)
144	
145	        Ok(())
146	    }
147	}
148	
149	// ── unified enum ─────────────────────────────────────────────────────────────
150	
151	/// Active rate-limiter backend.  Constructed once at startup from
152	/// `AppConfig::rate_limit_backend` and passed to `IpGuard`.
153	#[derive(Clone)]
154	pub enum RateLimiter {
155	    Memory(InMemoryLimiter),
156	    Postgres(PostgresLimiter),
157	}
158	
159	impl Default for RateLimiter {
160	    /// Defaults to the in-memory backend for backward compatibility.
161	    fn default() -> Self {
162	        Self::Memory(InMemoryLimiter::default())
163	    }
164	}
165	
166	impl RateLimiter {
167	    /// Construct the appropriate backend from a configuration string.
168	    /// Accepts `"postgres"` (case-insensitive) for the Postgres backend;
169	    /// any other value uses the in-memory backend.
170	    pub fn from_config(backend: &str, pool: Option<PgPool>) -> Self {
171	        if backend.eq_ignore_ascii_case("postgres") {
172	            if let Some(p) = pool {
173	                return Self::Postgres(PostgresLimiter::new(p));
174	            }
175	            tracing::warn!(
176	                "rate_limit_backend=postgres but no pool supplied; \
177	                 falling back to memory"
178	            );
179	        }
180	        Self::Memory(InMemoryLimiter::default())
181	    }
182	
183	    /// Returns `Ok(())` if the request is allowed, `Err(retry_after_seconds)`
184	    /// if the sliding window is full.
185	    pub async fn check(&self, ip: &str) -> Result<(), u64> {
186	        match self {
187	            Self::Memory(m) => m.check(ip),
188	            Self::Postgres(p) => p.check(ip).await,
189	        }
190	    }
191	}
192	
193	// ── tests ─────────────────────────────────────────────────────────────────────
194	
195	#[cfg(test)]
196	mod tests {
197	    use super::*;
198	
199	    fn memory_limiter() -> RateLimiter {
200	        RateLimiter::Memory(InMemoryLimiter::default())
201	    }
202	
203	    #[tokio::test]
204	    async fn allows_up_to_limit_then_rejects() {
205	        let rl = memory_limiter();
206	        for _ in 0..rate_limit_per_min() {
207	            assert!(rl.check("1.2.3.4").await.is_ok());
208	        }
209	        assert!(rl.check("1.2.3.4").await.is_err());
210	        // different IP not affected
211	        assert!(rl.check("9.9.9.9").await.is_ok());
212	    }
213	
214	    #[tokio::test]
215	    async fn multiple_ips_are_independent() {
216	        let rl = memory_limiter();
217	        for _ in 0..rate_limit_per_min() {
218	            rl.check("10.0.0.1").await.ok();
219	        }
220	        assert!(rl.check("10.0.0.1").await.is_err());
221	        // a different IP starts with a fresh window
222	        assert!(rl.check("10.0.0.2").await.is_ok());
