1	use chrono::Utc;
2	use gloo::net::http::{Request, Response};
3	use hmac::{Hmac, Mac};
4	use sha2::Sha256;
5	use uuid::Uuid;
6	use web_sys::FormData;
7	
8	type HmacSha256 = Hmac<Sha256>;
9	
10	/// Browser-side signed-request client.
11	///
12	/// Canonical string format (mirrors `security::signing` on the server):
13	///   `METHOD\nPATH\nTIMESTAMP\nNONCE`
14	/// where PATH is the **bare resource path without query string**
15	/// (e.g. `/api/v1/analytics/dashboard` even when called as
16	/// `/api/v1/analytics/dashboard?institution_id=abc`).
17	/// HMAC-SHA256 with the per-token signing key returned at login.
18	pub struct ApiClient {
19	    pub api_token: String,
20	    pub signing_key: String,
21	}
22	
23	fn sign(key: &str, canonical: &str) -> String {
24	    let mut mac = HmacSha256::new_from_slice(key.as_bytes()).expect("hmac");
25	    mac.update(canonical.as_bytes());
26	    hex::encode(mac.finalize().into_bytes())
27	}
28	
29	impl ApiClient {
30	    pub async fn get(&self, path: &str) -> Result<Response, String> {
31	        self.send("GET", path, None::<&str>).await
32	    }
33	    pub async fn post_json<S: serde::Serialize>(&self, path: &str, body: &S) -> Result<Response, String> {
34	        let body = serde_json::to_string(body).map_err(|e| e.to_string())?;
35	        self.send("POST", path, Some(body.as_str())).await
36	    }
37	
38	    /// Upload a file as multipart/form-data with the same HMAC signing headers.
39	    pub async fn post_multipart(&self, path: &str, form: FormData) -> Result<Response, String> {
40	        let ts = Utc::now().timestamp().to_string();
41	        let nonce = Uuid::new_v4().to_string();
42	        // Strip query string: only the bare path is signed (contract: PATH excludes '?...').
43	        let sign_path = path.split_once('?').map_or(path, |(p, _)| p);
44	        let canonical = format!("POST\n{}\n{}\n{}", sign_path, ts, nonce);
45	        let sig = sign(&self.signing_key, &canonical);
46	        Request::post(path)
47	            .header("x-silveroak-token", &self.api_token)
48	            .header("x-silveroak-timestamp", &ts)
49	            .header("x-silveroak-nonce", &nonce)
50	            .header("x-silveroak-signature", &sig)
51	            .body(form)
52	            .map_err(|e| e.to_string())?
53	            .send()
54	            .await
55	            .map_err(|e| e.to_string())
56	    }
57	    async fn send(&self, method: &str, path: &str, body: Option<&str>) -> Result<Response, String> {
58	        let ts = Utc::now().timestamp().to_string();
59	        let nonce = Uuid::new_v4().to_string();
60	        // Strip query string: only the bare path is signed (contract: PATH excludes '?...').
61	        let sign_path = path.split_once('?').map_or(path, |(p, _)| p);
62	        let canonical = format!("{}\n{}\n{}\n{}", method, sign_path, ts, nonce);
63	        let sig = sign(&self.signing_key, &canonical);
64	        let builder = match method {
65	            "POST" => Request::post(path),
66	            _ => Request::get(path),
67	        }
68	        .header("x-silveroak-token", &self.api_token)
69	        .header("x-silveroak-timestamp", &ts)
70	        .header("x-silveroak-nonce", &nonce)
71	        .header("x-silveroak-signature", &sig);
72	        let res = if let Some(body) = body {
73	            builder
74	                .header("content-type", "application/json")
75	                .body(body.to_string())
76	                .map_err(|e| e.to_string())?
77	                .send()
78	                .await
79	        } else {
80	            builder.send().await
81	        };
82	        res.map_err(|e| e.to_string())
83	    }
84	}
