20	#[actix_web::main]
21	async fn main() -> Result<()> {
22	    let _ = dotenvy::dotenv();
23	    tracing_subscriber::fmt()
24	        .with_env_filter(EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")))
25	        .json()
26	        .init();
27	
28	    let cfg = AppConfig::load()?;
29	    tracing::info!(env = %cfg.environment, "starting backend-api");
30	
31	    let pool = infrastructure::db::connect(&cfg.database_url).await?;
32	
33	    if cfg.run_migrations {
34	        infrastructure::migrations::run(&pool).await?;
35	    }
36	    if cfg.run_seeds {
37	        infrastructure::seed::run(&pool).await?;
38	    }
39	
40	    let bind = (cfg.server.host.clone(), cfg.server.port);
41	    let pool_data = web::Data::new(pool.clone());
42	
43	    // Build the rate-limiter backend from config.  For `postgres` we pass the
44	    // connection pool so each replica can share the sliding window.  Any other
45	    // value (including the default `memory`) yields the process-local backend.
46	    let limiter = RateLimiter::from_config(
47	        &cfg.rate_limit_backend,
48	        if cfg.rate_limit_backend.eq_ignore_ascii_case("postgres") {
49	            Some(pool.clone())
50	        } else {
51	            None
52	        },
53	    );
54	
55	    let signing_mode = SigningMode::from_config(&cfg.signing_mode);
56	    tracing::info!(
57	        host = %bind.0,
58	        port = bind.1,
59	        signing_mode = signing_mode.label(),
60	        rate_limit_backend = %cfg.rate_limit_backend,
61	        "listening",
62	    );
63	
64	    HttpServer::new(move || {
65	        App::new()
66	            .app_data(pool_data.clone())
67	            .wrap(IpGuard { limiter: limiter.clone() })
68	            .wrap(middleware::NormalizePath::trim())
69	            .wrap(middleware::Logger::default())
70	            .wrap(
71	                Cors::default()
72	                    // Allow the nginx proxy origin (port 8000) and direct frontend
73	                    // access (port 8081) used during local-network deployment and dev.
74	                    .allowed_origin("http://localhost:8000")
75	                    .allowed_origin("http://localhost:8081")
76	                    .allowed_origin("http://localhost:8080")
77	                    .allowed_methods(vec!["GET", "POST", "PUT", "PATCH", "DELETE"])
78	                    .allowed_headers(vec![
79	                        actix_web::http::header::CONTENT_TYPE,
80	                        actix_web::http::header::AUTHORIZATION,
81	                        // Custom signed-request headers
82	                        actix_web::http::header::HeaderName::from_static("x-silveroak-token"),
83	                        actix_web::http::header::HeaderName::from_static("x-silveroak-timestamp"),
84	                        actix_web::http::header::HeaderName::from_static("x-silveroak-nonce"),
85	                        actix_web::http::header::HeaderName::from_static("x-silveroak-signature"),
86	                        actix_web::http::header::HeaderName::from_static("x-silveroak-body-hash"),
87	                    ])
88	                    .max_age(3600),
89	            )
90	            .configure(move |cfg| routes::configure(cfg, signing_mode))
91	    })
92	    .bind(bind)?
93	    .run()
94	    .await?;
95	
96	    Ok(())
97	}
