14	// ── pagination ─────────────────────────────────────────────────────────────
15	#[derive(Debug, Deserialize)]
16	pub struct ListParams {
17	    pub page:     Option<i64>,
18	    pub per_page: Option<i64>,
19	    pub filter:   Option<String>,
20	    pub sort:     Option<String>,
21	    pub order:    Option<String>,
22	}
23	
24	impl ListParams {
25	    pub fn offset(&self) -> i64 { (self.page().saturating_sub(1)) * self.per_page() }
26	    pub fn page(&self) -> i64   { self.page.unwrap_or(1).max(1) }
27	    pub fn per_page(&self) -> i64 { self.per_page.unwrap_or(20).clamp(1, 200) }
28	    pub fn order_dir(&self) -> &str {
29	        match self.order.as_deref() { Some("desc") => "DESC", _ => "ASC" }
30	    }
31	}
32	
33	#[derive(Debug, Serialize)]
34	pub struct Page<T> {
35	    pub items:    Vec<T>,
36	    pub total:    i64,
37	    pub page:     i64,
38	    pub per_page: i64,
39	}
