41	// ── authorization helpers ──────────────────────────────────────────────────
42	pub fn assert_admin(p: &Principal) -> Result<(), ApiAppError> {
43	    p.require("admin:users")  // admin:users implies institution-admin level
44	}
45	
46	/// Verify that the institution_id is accessible to the principal (either
47	/// they hold scope:any, or they have an explicit institution scope for it).
48	pub fn assert_institution_scope(p: &Principal, institution_id: Uuid) -> Result<(), ApiAppError> {
49	    if p.permissions.contains("scope:any") { return Ok(()); }
50	    let ok = p.scopes.iter().any(|s| {
51	        s.kind == crate::security::rbac::ScopeKind::Institution
52	            && s.reference == institution_id.to_string()
53	    });
54	    if ok { Ok(()) } else {
55	        Err(ApiAppError::Forbidden("institution scope required".into()))
56	    }
57	}
